import sys

LIMIT = 10 ** 9

def solve():
    data = sys.stdin.read().split()
    it = iter(data)
    t = int(next(it))
    out_lines = []
    for _ in range(t):
        n = int(next(it))
        q = int(next(it))
        A = [int(next(it)) for _ in range(n)]
        # ans[L] 表示所有长度为 L 的区间能量值之和，1-indexed
        ans = [0] * (n + 1)

        i = 0
        while i < n:
            if A[i] == 0:
                # 包含 0 的区间能量值均为 0，跳过
                i += 1
                continue

            j = i
            while j < n and A[j] != 0:
                j += 1
            seg = A[i:j]
            m = j - i

            # 判断是否全为 1
            if all(x == 1 for x in seg):
                # 全 1 段：长度为 L 的区间有 m-L+1 个，贡献均为 1
                for L in range(1, m + 1):
                    ans[L] += (m - L + 1)
            else:
                # 非全 1 段：枚举起点，累乘直到超限
                for start in range(m):
                    prod = 1
                    for end in range(start, m):
                        if prod > LIMIT // seg[end]:
                            break
                        prod *= seg[end]
                        if prod > LIMIT:
                            break
                        length = end - start + 1
                        ans[length] += prod
            i = j

        # 回答询问
        for _ in range(q):
            L = int(next(it))
            out_lines.append(str(ans[L]))
        # 多组数据之间不需要额外空行，但按题目要求直接输出
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
